/**
 * Lifecycle states of a Knowledge Object.
 */
export type KnowledgeLifecycle = 'GENERATED' | 'VALIDATED' | 'APPROVED' | 'FROZEN';

/**
 * Defines the source of the knowledge.
 * Can be derived from Master Data, generated by AI, or manually entered.
 */
export interface KnowledgeSource {
  origin: 'MASTER_DATA' | 'AI_GENERATED' | 'MANUAL_ENTRY' | 'POLICY_CENTER';
  referenceId?: string;
  serviceVersion?: string;
}

/**
 * Represents the confidence level of the generated/extracted knowledge.
 * Especially useful for AI-generated knowledge.
 */
export interface KnowledgeConfidence {
  score: number; // 0 to 1
  reasoning?: string;
  flags?: string[];
}

/**
 * Metadata accompanying every Canonical Knowledge Object.
 */
export interface KnowledgeMetadata {
  id: string;
  domain: string;
  version: string;
  createdAt: string;
  lifecycle: KnowledgeLifecycle;
  source: KnowledgeSource;
  confidence?: KnowledgeConfidence;
}

/**
 * The base interface for all Canonical Knowledge Objects.
 * Builders MUST output objects implementing this interface.
 */
export interface CanonicalKnowledgeObject<T> {
  metadata: KnowledgeMetadata;
  data: T;
}
